// Number of questions per set that must be answered correctly to pass.
// The real 仮免許学科試験 is 50 questions and requires 45 correct (90%).
const EXAM_QUESTION_COUNT = 50;
const EXAM_PASS_COUNT = 45;

// ---------------------------------------------------------------------
// Data integrity (checked once, at load time)
// ---------------------------------------------------------------------
// Self-check: bad data is reported in the console right away instead of
// surfacing later as a broken exam screen (a set with the wrong number of
// questions, an answer that is not 正 / 誤, a question number typed into `q`
// even though the UI already prints 問N from the array index).
// Returns the problem list so it can also be asserted from a test runner.
function validateExamData(sets) {
    const problems = [];
    sets.forEach(set => {
        const list = Array.isArray(set.questions) ? set.questions : [];
        if (list.length !== EXAM_QUESTION_COUNT) {
            problems.push(set.id + ': ' + list.length + ' questions, expected ' + EXAM_QUESTION_COUNT);
        }
        list.forEach((item, i) => {
            const at = set.id + ' 問' + (i + 1);
            if (!item.q || !item.explanation || !item.myanmar) {
                problems.push(at + ': missing q / explanation / myanmar');
            }
            if (item.answer !== '正' && item.answer !== '誤') {
                problems.push(at + ': answer must be 正 or 誤 (got "' + item.answer + '")');
            }
            if (/^\s*\d+\s*[.．]/.test(item.q || '')) {
                problems.push(at + ': remove the question number from q (the UI prints it)');
            }
            if (item.furigana && item.furigana.replace(/\{([^{}|]+)\|[^{}]+\}/g, '$1') !== item.q) {
                problems.push(at + ': furigana must reproduce q once the {base|れあでぃんg} marks are removed');
            }
        });
    });
    if (problems.length && typeof console !== 'undefined') {
        console.warn('[examdata] ' + problems.length + ' data problem(s):\n- ' + problems.join('\n- '));
    }
    return problems;
}

// The sets are pure reference data: script.js only reads them (pictures live
// in a separate examPhotos map), so freeze everything to make an accidental
// write such as item.answer = ... or questions.push(...) fail fast.
function freezeExamData(sets) {
    sets.forEach(set => {
        set.questions.forEach(item => Object.freeze(item));
        Object.freeze(set.questions);
        Object.freeze(set);
    });
    return Object.freeze(sets);
}

validateExamData(examQuestionSets);
freezeExamData(examQuestionSets);

// Expose to the global scope (loaded via a plain <script> tag in index.html).
